PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE runs (
  id             TEXT PRIMARY KEY,
  topic          TEXT NOT NULL,
  goals          TEXT NOT NULL,          -- JSON array
  status         TEXT NOT NULL,          -- running | done | stopped | failed
  reason         TEXT,                   -- why it terminated
  iterations     INTEGER NOT NULL DEFAULT 0,
  max_iterations INTEGER NOT NULL,
  report         TEXT,                   -- final synthesis
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL
);
CREATE TABLE sources (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id     TEXT NOT NULL,
  url        TEXT NOT NULL,
  status     TEXT NOT NULL DEFAULT 'pending',  -- pending | fetched | failed
  error      TEXT,
  chunks     INTEGER NOT NULL DEFAULT 0,
  depth      INTEGER NOT NULL DEFAULT 0,       -- 0 = seed, >0 = model-proposed
  created_at INTEGER NOT NULL,
  UNIQUE (run_id, url)
);
CREATE TABLE findings (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id     TEXT NOT NULL,
  n          INTEGER NOT NULL,           -- iteration number
  source_url TEXT,
  finding    TEXT NOT NULL,
  progress   TEXT,                       -- model's self-assessment
  created_at INTEGER NOT NULL
, leaked TEXT);
CREATE TABLE control (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "usage_by_day_legacy" (
  day     TEXT NOT NULL,
  model   TEXT NOT NULL,
  neurons REAL NOT NULL DEFAULT 0,
  calls   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (day, model)
);
CREATE TABLE events (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  key        TEXT NOT NULL,        -- normalised company + stage
  company    TEXT NOT NULL,
  sector     TEXT,
  amount     TEXT,
  stage      TEXT,
  investors  TEXT,
  event_date TEXT,
  source_url TEXT,                 -- resolved from the [S#] marker, never model-written
  raw        TEXT NOT NULL,        -- the line as written, so a bad key can be audited
  run_id     TEXT NOT NULL,
  n          INTEGER NOT NULL,
  first_seen INTEGER NOT NULL, country TEXT,
  UNIQUE (key)
);
CREATE TABLE usage (
  id      INTEGER PRIMARY KEY AUTOINCREMENT,
  at      INTEGER NOT NULL,
  day     TEXT NOT NULL,
  model   TEXT NOT NULL,
  neurons REAL NOT NULL DEFAULT 0,
  calls   INTEGER NOT NULL DEFAULT 1
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_sources_claim ON sources (run_id, status, id);
CREATE INDEX idx_findings_run ON findings (run_id, n);
CREATE UNIQUE INDEX idx_findings_unique ON findings (run_id, n);
CREATE INDEX idx_events_seen ON events (first_seen DESC);
CREATE INDEX idx_events_run ON events (run_id, first_seen);
CREATE INDEX idx_usage_at ON usage(at);
CREATE INDEX idx_usage_day_model ON usage(day, model);
