INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('d2cd8b42','New Zealand early-stage technology investment','["Identify which funds invest at seed stage in New Zealand"]','done','max-iterations',1,1,replace('## Identify which funds invest at seed stage in New Zealand\n**Answered**\nThe New Zealand Growth Capital Partners'' Aspire fund invests at the seed stage in New Zealand, targeting early-stage Kiwi technology start-ups at proof of concept, seed, and early expansion investment stages, as stated on their website: https://nzgcp.co.nz/\n\n## Gaps\nA follow-up run should target identifying other funds that invest at the seed stage in New Zealand, as the current findings only mention one specific fund.','\n',char(10)),1786493493973,1786493535970);
