INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('9174a7bc','The Australian AI startup ecosystem in 2026: which sectors the companies cluster in and how they are funded.','["Identify the main sectors where Australian AI startups concentrate, and which are growing fastest","Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds"]','done','sources-exhausted',5,6,replace('## Identify the main sectors where Australian AI startups concentrate, and which are growing fastest\n**Partial**\nAustralian AI startups are present in the biotech sector, with 6 startups scoring $13.5 million from biotech grants fund CUREator+, indicating growth in the health tech and biotech areas (https://startupdaily.net/feed). The Australian technology sector contributes $248.5 billion (8.9% of GDP) and is the fastest-growing productivity engine, with its growth underpinned by the startup sector (https://innovationaus.com/feed). However, specific details on the main sectors where Australian AI startups concentrate, aside from biotech, are not stated in the sources.\n\n## Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds\n**Unanswered**\nThe findings do not provide information on the most active investors in Australian AI, typical stages, and notable recent rounds, aside from mentioning that 6 Australian AI startups in the biotech sector received $13.5 million from the biotech grants fund CUREator+ (https://startupdaily.net/feed).\n\n## Gaps\nA follow-up run should target the following areas:\n- Identifying the main sectors where Australian AI startups concentrate, aside from biotech\n- Mapping the funding landscape, including the most active investors in Australian AI, typical stages, and notable recent rounds\n- Providing more specific data on the growth rates of different sectors within the Australian AI startup ecosystem.','\n',char(10)),1786596456466,1786600844698);
