INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('ec5d3909','The Australian AI startup ecosystem in 2026: which sectors the companies cluster in and how they are funded.','["Identify the main sectors where Australian AI startups concentrate, and which are growing fastest","Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds"]','done','sources-exhausted',5,6,replace('## Identify the main sectors where Australian AI startups concentrate, and which are growing fastest\n**Partial**\nAustralian AI startups concentrate in sectors such as fintech, biotechnology, medical technology, digital health, space, robotics, agritech, climate, education, and sports technology, with companies like Visaible.ai in travel, Stirling in finance, and Canva and Sophiie AI in business strategy (https://startupdaily.net/feed, https://techcouncil.com.au/feed). Technical jobs in regional Australia grew by 12%, indicating a growing demand for technical skills. However, the sources do not specify which sectors are growing the fastest.\n\n## Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds\n**Partial**\nNotable recent funding rounds include $1 million for Visaible.ai, $5 million for Sophiie AI, and $3.15 million for Stirling, led by investors like Blackbird (https://startupdaily.net/feed, https://techcouncil.com.au/feed). However, the sources do not provide a comprehensive map of the funding landscape, including the most active investors in Australian AI and typical stages.\n\n## Gaps\nA follow-up run should target the identification of the fastest-growing sectors in the Australian AI startup ecosystem, as well as a more comprehensive mapping of the funding landscape, including the most active investors and typical investment stages. Additionally, more specific data on the growth rates of different sectors and the investment amounts would be beneficial.','\n',char(10)),1786982438093,1786986876329);
INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('f9da95d4','The Australian AI startup ecosystem in 2026: which sectors the companies cluster in and how they are funded.','["Identify the main sectors where Australian AI startups concentrate, and which are growing fastest","Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds"]','done','sources-exhausted',5,6,replace('## Identify the main sectors where Australian AI startups concentrate, and which are growing fastest\n**Partial**\nAustralian AI startups are found in sectors such as travel (Visaible.ai), construction (Sophiie AI), and data centers (NextDC) https://startupdaily.net/feed. The Australian tech workforce has software engineering roles growing by 7% year-on-year, and technical jobs in regional Australia growing by 12% over 5 years https://techcouncil.com.au/feed. However, the fastest-growing sectors among Australian AI startups are not specified in the findings.\n\n## Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds\n**Partial**\nNotable recent funding rounds include $1 million for Visaible.ai and $5 million for Sophiie AI https://startupdaily.net/feed. However, the most active investors in Australian AI, typical stages of funding, and other notable recent rounds are not specified in the findings.\n\n## Gaps\nA follow-up run should target the identification of the fastest-growing sectors among Australian AI startups, the most active investors in Australian AI, and the typical stages of funding for these startups. Additionally, more information on notable recent funding rounds and the overall funding landscape of Australian AI startups is needed to fully map the funding landscape.','\n',char(10)),1787068838235,1787073225571);
