INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('f2539796','The Australian AI startup ecosystem in 2026: which sectors the companies cluster in and how they are funded.','["Identify the main sectors where Australian AI startups concentrate, and which are growing fastest","Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds"]','done','max-iterations',2,2,replace('## Identify the main sectors where Australian AI startups concentrate, and which are growing fastest\n**Unanswered**\nThe findings do not provide information on the main sectors where Australian AI startups concentrate or which are growing fastest, as they focus on the broader technology sector and workforce trends, with no specific data on AI startups (https://techcouncil.com.au/feed).\n\n## Map the funding landscape: most active investors in Australian AI, typical stages, and notable recent rounds\n**Unanswered**\nThe findings do not provide information on the funding landscape of Australian AI startups, including most active investors, typical stages, or notable recent rounds, as they focus on the overall technology sector''s contribution to GDP and workforce trends, with no specific data on AI startup funding (https://techcouncil.com.au/feed).\n\n## Gaps\nA follow-up run should target the following areas:\n- Specific sectors where Australian AI startups concentrate\n- Growth rates of these sectors\n- Most active investors in Australian AI startups\n- Typical funding stages for Australian AI startups\n- Notable recent funding rounds for Australian AI startups','\n',char(10)),1787086941418,1787088051786);
