INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('35e0c08b','Australian AI and tech funding: track new events daily and flag divergence from the baseline.','["Record every new Australian AI or tech funding event in today''s sources: company, sector, amount, stage, investors, date. Report only events not already in the ledger.","Flag where today''s events diverge from the baseline: a sector it does not list among the concentrations, an investor it does not rank as active, or a round size outside its stated range for that stage."]','done','sources-exhausted',3,5,replace('## New events\n* Nybro — biotech, $20 million, Seed, QIC Ventures, no date, https://startupdaily.net/feed\n\n## Divergence from baseline\nNone\n\n## Notes\nNo new Australian AI or tech funding events were found in sources https://techcouncil.com.au/feed and https://smartcompany.com.au/feed.','\n',char(10)),1787155260450,1787157524183);
