INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('dd207e98','Australian AI and tech funding: track new events daily and flag divergence from the baseline.','["Record every new Australian AI or tech funding event in todays sources.","Flag where todays events diverge from the baseline."]','done','max-iterations',1,1,replace('## New events\nNone today.\n\n## Divergence from baseline\nNone.\n\n## Notes\nNybro''s Seed round has been doubled to $20 million, supported by QIC, as reported by https://startupdaily.net/feed. \nThis is a notable increase in funding. \nFurther details are available in the source article.','\n',char(10)),1787176694573,1787176709795);
INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('ab39eff8','Australian AI and tech funding: track new events daily and flag divergence from the baseline.','["Record every new Australian AI or tech funding event in today''s sources: company, sector, amount, stage, investors, date. Report only events not already in the ledger.","Flag where today''s events diverge from the baseline: a sector it does not list among the concentrations, an investor it does not rank as active, or a round size outside its stated range for that stage."]','done','sources-exhausted',3,5,replace('## New events\n* Seitec — defence tech, $4 million, Thu, 20 Aug 2026 https://startupdaily.net/feed\n\n## Divergence from baseline\nSeitec''s sector, defence tech, is not explicitly listed in the baseline''s sector distribution, although it can be mapped to the ''Space & defence'' sector https://startupdaily.net/feed.\n\n## Notes\nOnly one new funding event was recorded: Seitec''s $4 million funding.\nThe baseline already recorded Nybro''s funding, so it is not a new event https://startupdaily.net/feed.','\n',char(10)),1787241609310,1787243867631);
INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('5b6594b2','Australian AI and tech funding: track new events daily and flag divergence from the baseline.','["Record every new Australian AI or tech funding event in today''s sources: company, sector, amount, stage, investors, date. Report only events not already in the ledger.","Flag where today''s events diverge from the baseline''s SECTOR taxonomy: a funded company whose sector maps onto NONE of the taxonomy''s rows. A sector that maps onto a row under a different name is not a divergence — the test is ''does not map'', not ''is not listed verbatim''. Do NOT judge round size: code checks that against the baseline''s own flag table. Do NOT flag investors: the baseline ranks none, so an unfamiliar investor is evidence of nothing."]','done','sources-exhausted',1,5,replace('## New events\n* Vessev — electric ferry, $27 million, Series A https://startupdaily.net/feed\n* Bower — AI-based science research, $2 million, pre-Seed https://startupdaily.net/feed\n\n## Round size vs baseline (B3)\n* Vessev — $27 million (Series A): within $6.2M–$55.8M for Series A.\n* Bower — $2 million (pre-Seed): within $0.4M–$3.9M for Angel / Pre-Seed.\n\n## Divergence from baseline\nNone.','\n',char(10)),1787328054624,1787328102421);
INSERT INTO "runs" ("id","topic","goals","status","reason","iterations","max_iterations","report","created_at","updated_at") VALUES('0255dcba','Australian and New Zealand AI and tech funding: track new events daily and flag divergence from the baseline.','["Record every new AI or tech funding event in today''s sources: company, sector, amount, stage, investors, date, COUNTRY. Report only events not already in the ledger. State the country only where the material says or clearly implies it — a ''Kiwi'' startup or one based in Auckland is New Zealand; Sydney, Melbourne, Brisbane, Perth and Canberra are Australia. Where it does not, write ''-''. Do not infer a country from the publication.","Flag where today''s events diverge from the baseline''s SECTOR taxonomy: a funded company whose sector maps onto NONE of the taxonomy''s rows. A sector that maps onto a row under a different name is not a divergence — the test is ''does not map'', not ''is not listed verbatim''. ONLY for companies in the country the baseline covers: it is an Australian baseline, so a New Zealand or other company diverges from nothing and must not be flagged. Do NOT judge round size: code checks that against the baseline''s own flag table. Do NOT flag investors: the baseline ranks none, so an unfamiliar investor is evidence of nothing."]','done','sources-exhausted',1,5,replace('## New events\nNone today.\n\n## Round size vs baseline (B3)\nNo new events to check.\n\n## Divergence from baseline\nNone.','\n',char(10)),1787414455878,1787414478009);
