INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(152,'ab39eff8',1,'https://startupdaily.net/feed','Seitec, a defence tech startup, has raised $4 million in funding (https://startupdaily.net/feed), and Nybro, a biotech company, has doubled its Seed round to $20 million (https://startupdaily.net/feed), which is within the expected range for a Seed round according to the baseline [B3], but the baseline already recorded Nybro''s funding, so only Seitec''s funding is new, and its sector, defence tech, is not explicitly listed in the baseline''s sector distribution, but it can be mapped to the ''Space & defence'' sector [B1], and its amount is within the expected range for a Seed round [B3], and the investors are not explicitly listed, but ACTivate Capital is mentioned as a category (https://startupdaily.net/feed), which is not enough information to determine if it is a divergence from the baseline''s investor list [B2]','Goal 1 is partially advanced with one new funding event recorded, and Goal 2 is partially advanced with no divergence from the baseline''s sector distribution or round size range found, but the investor list divergence could not be determined',1787241634532,'["Nybro"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(153,'ab39eff8',2,'https://techcouncil.com.au/feed','No new Australian AI or tech funding events were found in the provided source (https://techcouncil.com.au/feed), as it does not mention any specific funding amounts or rounds.','Goal 1 is still open, as no new funding events were found. Goal 2 is also open, as there are no new events to compare to the baseline.',1787242735777,NULL);
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(154,'ab39eff8',3,'https://smartcompany.com.au/startupsmart/feed','Eight ANZ startups raised a total of $67.4 million this week, but the material does not provide a breakdown of the individual funding amounts, so no new events can be recorded (https://smartcompany.com.au/startupsmart/feed).','Goal 1 is partially advanced, but the material lacks specific funding amounts for the eight startups, so no new events can be added. Goal 2 is not advanced as there are no new events to compare against the baseline.',1787243862321,NULL);
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(155,'5b6594b2',1,'https://startupdaily.net/feed','New funding events were found for Vessev, Bower, and Seitec, with amounts of $27 million, $2 million, and $4 million respectively (https://startupdaily.net/feed).','Goal 1 is partially answered, with new funding events recorded. Goal 2 is still open, as no divergence from the baseline''s SECTOR taxonomy was found.',1787328089424,'["Seitec"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(156,'0255dcba',1,'https://startupdaily.net/feed','New funding events were found for Vessev, Bower, and Seitec, with Vessev raising $27 million in a Series A round (https://startupdaily.net/feed), Bower raising $2 million in a pre-Seed round (https://startupdaily.net/feed), and Seitec raising $4 million (https://startupdaily.net/feed).','Goal 1 is partially advanced, with new funding events recorded. Goal 2 is not yet addressed as the baseline''s sector taxonomy is not fully compared to the new events.',1787414473850,'["Vessev","Bower","Seitec"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(157,'84728ae6',1,'https://startupdaily.net/feed','New funding events were found for Vessev, Bower, and Seitec, with amounts of $27 million, $2 million, and $4 million respectively (https://startupdaily.net/feed). Vessev is a Kiwi electric ferry startup, Bower is an AI-based science research startup, and Seitec is a Canberra defence tech startup (https://startupdaily.net/feed).','Goal 1 is partially advanced, with new funding events recorded. Goal 2 is not advanced as no divergence from the baseline''s SECTOR taxonomy was found for Australian companies.',1787500879031,'["Vessev","Bower","Seitec"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(158,'3584b53e',1,'https://startupdaily.net/feed','New funding events were found for Vessev, Bower, and Seitec, but these were already recorded; new events were also found for Galileo Ventures, TikTok, Canva, and others, but only those with a clear funding amount and company information are recorded, such as Bower, which raised $2 million in pre-Seed funding (https://startupdaily.net/feed), and Seitec, which raised $4 million (https://startupdaily.net/feed), and Vessev, which raised $27 million in Series A funding (https://startupdaily.net/feed); Galileo Ventures closed its second major fund with an undisclosed amount (https://startupdaily.net/feed); no new events were found that diverge from the baseline''s sector taxonomy (https://startupdaily.net/feed)','Goal 1 is partially advanced, with new funding events recorded, but more events may still be found; Goal 2 is not advanced, as no new events were found that diverge from the baseline''s sector taxonomy',1787587312835,'["Vessev","Bower","Seitec"]');
