INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(165,'c8eab44a',1,'https://startupdaily.net/feed','Gridsight raised $36 million in a Series B round (https://startupdaily.net/feed), and Apate.AI raised $11.4 million in a Seed round (https://startupdaily.net/feed), while Airwallex invested $1 million in 10 AI startups (https://startupdaily.net/feed), but the country of Apate.AI is not stated in the material, and Airwallex''s investment is not a funding event for Airwallex itself, but for the 10 AI startups, which are not named, so only Gridsight''s event can be fully recorded, and Apate.AI''s event is recorded without a country','The first goal is partially advanced, with some funding events recorded, but more events may be present in the material that are not yet recorded, and the country of some companies is not stated',1788278494288,'["Apate.AI","Airwallex"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(166,'acc7b30e',1,'https://startupdaily.net/feed','GonGlobal, an IVF startup, raised $1.2 million (https://startupdaily.net/feed), and Drumbeat, a Kiwi comms startup, raised NZ$2M (https://startupdaily.net/feed), while Gridsight, an energy network management platform, raised $36 million in a Series B round (https://startupdaily.net/feed), and Apate.AI, an anti-scammer startup, raised $11.4 million in a Seed round (https://startupdaily.net/feed), but the country for Apate.AI is not stated in the material (https://startupdaily.net/feed), and the baseline only covers Australia, so Apate.AI''s sector is not checked against it (https://startupdaily.net/feed)','Goal 1 is partially answered with new funding events, but the country for some companies is not stated or is outside Australia, so their sectors are not checked against the baseline',1788364875272,'["Gridsight","Apate.AI"]');
