INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(172,'198a8273',1,'https://startupdaily.net/feed','No new funding events were found in the provided source (https://startupdaily.net/feed) that have not already been recorded, except for the $16 million Series A funding of Pearler, which was already recorded, and the $3 million funding of ENA Respiratory, also already recorded. However, the source does mention that Expert360''s founder and early investors missed out in a $16 million exit, but this is not a funding event. Diraq''s installation of a quantum computer in Equinix''s Sydney data centre is also mentioned, but no funding amount is specified. Therefore, no new events are added to the ledger.','Goal 1 is partially advanced, as no new funding events were found, but the search for new events is ongoing.',1788796896249,'["ENA Respiratory","Pearler"]');
