INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(183,'74025166',1,'https://startupdaily.net/feed','Buildkite raised $21 million earlier this year after posting massive losses (https://startupdaily.net/feed), and ReFresh raised $2.5 million in a Seed round (https://startupdaily.net/feed). Airtree is offering $350,000 to ANZ founders to kick off in Silicon Valley (https://startupdaily.net/feed). Evatto raised $1.02 million in a pre-Seed round (https://startupdaily.net/feed).','Goal 1 is partially answered, with new funding events recorded. Goal 2 is not answered as there is no divergence from the baseline''s SECTOR taxonomy in the new events.',1789747247788,'["ReFresh","Evatto"]');
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(184,'a4881f0f',1,'https://startupdaily.net/feed','Buildkite raised $21 million earlier this year after posting massive losses (https://startupdaily.net/feed), and ReFresh raised $2.5 million in a Seed round (https://startupdaily.net/feed). Evatto raised $1.02 million in a pre-Seed round (https://startupdaily.net/feed). The sectors of these companies do not diverge from the baseline''s taxonomy as Buildkite''s sector is not stated, ReFresh is in the mental health sector which maps to healthtech, and Evatto''s sector is not explicitly stated but is related to enterprise events and AI, which could map to AI models & data infrastructure or vertical business software (https://startupdaily.net/feed).','Goal 1 is partially advanced, with some new funding events recorded. Goal 2 is also partially advanced, with no divergence from the baseline''s taxonomy found for the recorded events.',1789833647338,'["Buildkite","ReFresh","Evatto"]');
