INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(186,'cbecafe8',1,'https://startupdaily.net/feed','Amber Electric raised $78.5 million in a Series E round, according to Startup Daily (https://startupdaily.net/feed). The company is based in Australia, as implied by the publication''s focus on the Australian tech ecosystem (https://startupdaily.net/feed). The sector is climate tech, which maps onto the ''Climate & energy'' row in the baseline''s taxonomy (https://startupdaily.net/feed).','Goal 1 is partially answered, with one new funding event recorded. Goal 2 is not answered, as there is no divergence from the baseline''s sector taxonomy in the recorded event.',1790006459825,NULL);
INSERT INTO "findings" ("id","run_id","n","source_url","finding","progress","created_at","leaked") VALUES(187,'b12daf5f',1,'https://startupdaily.net/feed','Heidi, an AI company, raised $140m in a Series C round (https://startupdaily.net/feed), and OpenDebt, an AI debt recovery fintech, secured $2m in a pre-Seed round (https://startupdaily.net/feed), while HEO Robotics, a space monitoring startup, raised $37m in a Series B round (https://startupdaily.net/feed), and Amber Electric, a climate tech company, raised $78.5m in a Series E round (https://startupdaily.net/feed), which was already recorded, so it is not included in the events list. Heidi''s sector, AI, is in the baseline''s taxonomy (https://startupdaily.net/feed), and OpenDebt''s sector, fintech, is also in the baseline''s taxonomy (https://startupdaily.net/feed). HEO Robotics'' sector, space, is in the baseline''s taxonomy as well (https://startupdaily.net/feed).','Goal 1 is partially answered, with new funding events recorded, but more events may be found in future iterations. Goal 2 is also partially answered, with no divergence from the baseline''s sector taxonomy found in the new events.',1790092867501,'["Amber Electric"]');
